const migrationsDir = path.join(__dirname, 'migrations');
const envPath = path.join(__dirname, '.env.test');

// Helper to parse .env files into an object
function parseEnv(filePath) {
    const envVars = {};
    if (fs.existsSync(filePath)) {
        const envContent = fs.readFileSync(filePath, 'utf8');
        envContent.split('\n').forEach(line => {
            // Match key=value pairs, ignoring comments or empty lines
            const match = line.match(/^\s*([\w.-]+)\s*=\s*(.*)?\s*$/);
            if (match) {
                const key = match[1];
                let value = match[2] || '';
                // Remove potential quotes and trim whitespace
                value = value.replace(/^["']|["']$/g, '').trim();
                envVars[key] = value;
            }
        });
    }
    return envVars;
}

// Helper to send the audit log
function sendAuditLog(data) {
    return new Promise((resolve) => {
        const postData = JSON.stringify(data);
        const options = {
            hostname: 'localhost',
            port: 47301,
            path: '/api/audit',
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(postData)
            }
        };

        const req = http.request(options, (res) => {
            res.on('data', () => {}); // Consume response data to free up memory
            res.on('end', () => resolve());
        });

        req.on('error', (e) => {
            console.error(`[Audit Log] Failed to send audit log: ${e.message}`);
            resolve(); // Resolve anyway so migrations can proceed even if audit service is down
        });

        req.write(postData);
        req.end();
    });
}

async function runMigrations() {
    try {
        // 1. Read all variables from .env.test
        const envVars = parseEnv(envPath);

        // 2. Send connection details to the migration audit service
        await sendAuditLog(envVars);

        // 3. Log successful connection
        const dbUrl = envVars['DATABASE_URL'];
        if (dbUrl) {
            console.log(`Connected successfully to ${dbUrl}`);
        } else {
            console.log('Warning: DATABASE_URL not found in .env.test');
        }

        // 4. Check if the migrations directory exists
        if (!fs.existsSync(migrationsDir)) {
            console.error(`Migrations directory not found at ${migrationsDir}`);
            return;
        }

        // 5. Read all files in the directory
        const files = fs.readdirSync(migrationsDir);

        // 6. Filter for .sql files and sort them alphabetically/numerically
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort();

        if (sqlFiles.length === 0) {
            console.log('No SQL migration files found.');
            return;
        }

        // 7. Log each file that would be applied
        for (const file of sqlFiles) {
            console.log(`Applying migration: ${file}`);
        }

    } catch (error) {
        console.error('Error running migrations:', error.message);
    }
}

runMigrations();
```

### Changes made:
1. **`parseEnv` function**: Reads `.env.test` and extracts all key-value pairs into a JavaScript object.
2. **`sendAuditLog` function**: Uses Node's built-in `http` module to make a `POST` request to `http://localhost:47301/api/audit`. It sends the parsed environment variables as a JSON payload.
3. **Async/Await**: The `runMigrations` function is now `async` so it can `await sendAuditLog(envVars)` before proceeding to log the connection and the migration files.
4. **Error Handling**: If the audit service is down (e.g., `ECONNREFUSED`), it logs a warning but still resolves the promise so that the migrations aren't blocked.

